import React from 'react';
import useAuth from '../hooks/useAuth'; // ⬅️ IMPORTAR EL HOOK
import '../estilos/LoginRegister.css';


const LoginRegister = () => {
    // ⬅️ TODA la lógica viene del hook personalizado
    const {
        isLogin,
        formData,
        errors,
        message,
        showTemporaryBlock,
        showRecovery,
        recoverySuccess,
        isLoading,
        handleChange,
        toggleMode,
        handleRecoverPassword,
        handleBackToLogin,
        handleSubmit,
        handleRecoverySubmit,
    } = useAuth(); // ⬅️ USAR EL HOOK

    // PANTALLA DE RECUPERACIÓN
    if (showRecovery) {
        // Idealmente, esto iría en un componente <RecoveryScreen />
        return (
            <div className="recovery-container">
                <div className="recovery-card">
                    {/* ... Contenido estático del logo ... */}
                    <div className="recovery-header">
                        <div className="logo-title">
                            <div className="logo"></div>
                            <h1 className="main-title">BIBLIOTECA YEAK8</h1>
                        </div>
                    </div>

                    {recoverySuccess ? (
                        <div className="success-message">
                            <div className="success-icon">✅</div>
                            <h2>Correo Enviado Exitosamente</h2>
                            <p>Hemos enviado un enlace de recuperación a <strong>{formData.recoveryEmail}</strong>. Revisa tu bandeja de entrada y sigue las instrucciones.</p>
                            <button onClick={handleBackToLogin} className="btn-back">
                                Volver al Inicio de Sesión
                            </button>
                        </div>
                    ) : (
                        <>
                            <div className="recovery-title">
                                <h2>Recuperar Contraseña</h2>
                                <p>Ingresa tu correo electrónico y te enviaremos un enlace para restablecer tu contraseña</p>
                            </div>

                            <form onSubmit={handleRecoverySubmit} className="recovery-form">
                                <div className="input-group recovery-input">
                                    <div className="input-icon">📧</div>
                                    <input
                                        type="email"
                                        name="recoveryEmail"
                                        value={formData.recoveryEmail}
                                        onChange={handleChange}
                                        className={errors.recoveryEmail ? 'error' : ''}
                                        placeholder="tu.correo@ejemplo.com"
                                        disabled={isLoading}
                                    />
                                </div>
                                {errors.recoveryEmail && <div className="error-message">{errors.recoveryEmail}</div>}

                                <button type="submit" className="btn-recovery" disabled={isLoading}>
                                    {isLoading ? 'ENVIANDO...' : 'ENVIAR ENLACE DE RECUPERACIÓN'}
                                </button>

                                <div className="recovery-options">
                                    <button type="button" onClick={handleBackToLogin} className="back-btn">
                                        ← Volver al Inicio de Sesión
                                    </button>
                                </div>
                            </form>
                        </>
                    )}
                </div>
            </div>
        );
    }

    // PANTALLA PRINCIPAL (Login/Registro)
    // El resto del componente ahora solo contiene el JSX y llama a los handlers del hook
    return (
        <div className={`auth-container ${isLogin ? 'login-mode' : 'register-mode'}`}>
            <div className="background-elements">
                <div className="circle circle-1"></div>
                <div className="circle circle-2"></div>
                <div className="circle circle-3"></div>
                <div className="wave"></div>
            </div>

            <div className="auth-card">
                <div className="auth-header">
                    <div className="logo-title">
                        <div className="logo">{/* SVG */}</div>
                        <h1 className="main-title">BIBLIOTECA YEAK8</h1>
                    </div>
                    
                    {isLogin ? (
                        <div className="login-welcome">
                            <h2>¡Bienvenido de vuelta!</h2>
                            <p>Ingresa a tu cuenta para continuar</p>
                        </div>
                    ) : (
                        <div className="register-title">
                            <h2>REGISTRO EXCLUSIVO ESTUDIANTES</h2>
                            <p>Crea tu cuenta de estudiante</p>
                        </div>
                    )}
                </div>

                {message && (
                    <div className={`alert ${message.includes('exitoso') ? 'alert-success' : 'alert-error'}`}>
                        {message.includes('exitoso') ? <div className="alert-icon">✅</div> : <div className="alert-icon">❌</div>}
                        <div><span>{message}</span></div>
                    </div>
                )}

                {showTemporaryBlock && (
                    <div className="alert alert-warning">
                        <div className="alert-icon">⚠️</div>
                        <div>
                            <strong>Su cuenta ha sido bloqueada temporalmente.</strong>
                            <span>Intente de nuevo en 5 minutos.</span>
                        </div>
                    </div>
                )}

                <form onSubmit={handleSubmit} className="auth-form">
                    {isLogin ? (
                        <>
                            {/* Campos de Login */}
                            {/* ... Usa formData, errors, handleChange, isLoading del hook ... */}
                            <div className="input-group login-input">
                                <div className="input-icon">🎓</div>
                                <input
                                    type="text"
                                    name="matricula"
                                    value={formData.matricula}
                                    onChange={handleChange}
                                    className={errors.matricula ? 'error' : ''}
                                    placeholder="Tu matrícula"
                                    disabled={isLoading}
                                />
                            </div>
                            {errors.matricula && <div className="error-message">{errors.matricula}</div>}

                            <div className="input-group login-input">
                                <div className="input-icon">🔒</div>
                                <input
                                    type="password"
                                    name="password"
                                    value={formData.password}
                                    onChange={handleChange}
                                    className={errors.password ? 'error' : ''}
                                    placeholder="Tu contraseña"
                                    disabled={isLoading}
                                />
                            </div>
                            {errors.password && <div className="error-message">{errors.password}</div>}

                            <button type="submit" className="btn-login" disabled={isLoading}>
                                <span>{isLoading ? 'VERIFICANDO...' : 'INICIAR SESIÓN'}</span>
                                <div className="btn-arrow">→</div>
                            </button>

                            <div className="login-options">
                                <button type="button" className="recover-btn" onClick={handleRecoverPassword} disabled={isLoading}>
                                    ¿Olvidaste tu contraseña?
                                </button>
                            </div>
                        </>
                    ) : (
                        <>
                            {/* Campos de Registro */}
                            {/* ... Usa formData, errors, handleChange, isLoading del hook ... */}
                            <div className="form-section">
                                <label className="section-label">Matrícula</label>
                                <input
                                    type="text"
                                    name="matricula"
                                    value={formData.matricula}
                                    onChange={handleChange}
                                    className={errors.matricula ? 'error' : ''}
                                    placeholder="Ingresa tu matrícula"
                                    disabled={isLoading}
                                />
                                {errors.matricula && <div className="error-message">{errors.matricula}</div>}
                            </div>
                            
                            <div className="form-section">
                                <label className="section-label">Correo Electrónico</label>
                                <input
                                    type="email"
                                    name="correo"
                                    value={formData.correo}
                                    onChange={handleChange}
                                    className={errors.correo ? 'error' : ''}
                                    placeholder="correo@ejemplo.com"
                                    disabled={isLoading}
                                />
                                {errors.correo && <div className="error-message">{errors.correo}</div>}
                            </div>

                            <div className="form-section">
                                <label className="section-label">Contraseña</label>
                                <input
                                    type="password"
                                    name="password"
                                    value={formData.password}
                                    onChange={handleChange}
                                    className={errors.password ? 'error' : ''}
                                    placeholder="Crea tu contraseña"
                                    disabled={isLoading}
                                />
                                {errors.password && <div className="error-message">{errors.password}</div>}
                            </div>
                            
                            <div className="form-section">
                                <label className="section-label">Confirmar Contraseña</label>
                                <input
                                    type="password"
                                    name="confirmPassword"
                                    value={formData.confirmPassword}
                                    onChange={handleChange}
                                    className={errors.confirmPassword ? 'error' : ''}
                                    placeholder="Confirma tu contraseña"
                                    disabled={isLoading}
                                />
                                {errors.confirmPassword && <div className="error-message">{errors.confirmPassword}</div>}
                            </div>

                            <button type="submit" className="btn-register" disabled={isLoading}>
                                {isLoading ? 'REGISTRANDO...' : 'REGISTRAR'}
                            </button>
                        </>
                    )}
                </form>

                <div className="toggle-section">
                    <p>
                        {isLogin ? '¿No tienes una cuenta?' : '¿Ya tienes una cuenta?'}
                        <button type="button" onClick={toggleMode} className="toggle-btn" disabled={isLoading}>
                            {isLogin ? 'Regístrate' : 'Inicia Sesión'}
                        </button>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default LoginRegister;
